 const conditionalStyle=(row:number,col:number):Record<string,string>=>{const v=scalar({sheetId,row,col});if(typeof v!=='number')return {};let result:Record<string,string>={};const resolve=(ruleRange:CellRect,t:Threshold|{kind:string;value?:number},fallback:number):number=>{if(t.kind==='number'&&typeof t.value==='number')return t.value;if(t.kind==='minimum'||t.kind==='maximum'){let min=Infinity,max=-Infinity,found=false;for(let r=ruleRange.top;r<=ruleRange.bottom;r++)for(let c=ruleRange.left;c<=ruleRange.right;c++){const val=scalar({sheetId,row:r,col:c});if(typeof val==='number'&&Number.isFinite(val)){found=true;if(val<min)min=val;if(val>max)max=val;}}if(!found)return fallback;return t.kind==='minimum'?min:max;}return fallback;};for(const rule of sheet.properties.conditionalFormats){if(!contains(rule.range,row,col))continue;if(rule.kind==='colorScale'){const first=rule.stops[0],last=rule.stops.at(-1);if(first&&last)result={backgroundColor:colorScale(v,resolve(rule.range,first.threshold,0),resolve(rule.range,last.threshold,100),rule.stops.map(s=>s.color))};}if(rule.kind==='dataBar'){const minVal=resolve(rule.range,rule.min,0),maxVal=resolve(rule.range,rule.max,100);const percent=maxVal>minVal?Math.max(0,Math.min(100,100*(v-minVal)/(maxVal-minVal))):0;result={background:`linear-gradient(to right, ${rule.color} ${percent}%, transparent ${percent}%)`};}}return result;};
 useEffect(()=>{setValues({});setFormula(cellText(getCell(workbook,{sheetId,...active})));setExtraSelections([]);if(viewport.current){viewport.current.scrollTop=0;viewport.current.scrollLeft=0;}},[workbook.id,sheetId]);
